BEGIN;

INSERT INTO pages (id, site_id, name, url, title, page_type, status, meta_description,
                    nav_label, nav_order, in_header, in_footer, sections, build_status)
VALUES (gen_random_uuid(), '4851f6fc-71cf-4160-a270-e03d6d3e0732',
        'ai-data-trust-in-healthcare',
        '/blog/ai-data-trust-in-healthcare.html',
        'AI in Healthcare: The Data Is Most Sensitive, and Trust Is Falling | Leopardess Consulting',
        'blog-post', 'active',
        'Patient trust in medical AI fell 8 points in two years even as adoption grows. What the research says builds trust, cited and quoted.',
        NULL, 23, false, false,
        '["hero","article-body","call-to-action"]'::jsonb, 'pending');

INSERT INTO page_components (id, page_id, slot_name, position, component_id, content_data, build_status)
SELECT gen_random_uuid(), p.id, 'hero', 1, cc.id, $HEROJSON${"headline": "AI in Healthcare: The Data Is Most Sensitive, and Trust Is Falling", "subheadline": "Patient trust in medical AI dropped 8 points in two years, even as adoption grows. The research shows why, and exactly what closes the gap.", "background_image": "/assets/images/hero.jpg"}$HEROJSON$::jsonb, 'deployed'
FROM pages p, content_components cc
WHERE p.site_id='4851f6fc-71cf-4160-a270-e03d6d3e0732' AND p.name='ai-data-trust-in-healthcare' AND cc.name='hero';

INSERT INTO page_components (id, page_id, slot_name, position, component_id, content_data, build_status)
SELECT gen_random_uuid(), p.id, 'article-body', 2, cc.id, jsonb_build_object('content', $ARTBODY$<p><a href="/blog/can-you-trust-ai-with-your-data.html">This is the first of three deep dives</a> following our overview piece on trusting AI with data across industries. Healthcare carries the most sensitive personal data of any sector in that research, and the trust numbers move the most.</p><h2>Trust Is Falling, Not Rising, Even as Use Climbs</h2><p>The headline number from the most recent large survey of American attitudes is not encouraging, and it is worth sitting with before getting to the more useful finding underneath it:</p><blockquote>"Just 44% of Americans trust the use of AI in healthcare, down from 52% two years ago, according to Reach3 Insights and Rival Technologies' '2026 Digital Health Trends' of 1,043 survey respondents." — eMarketer, reporting Reach3 Insights/Rival Technologies, February 27, 2026</blockquote><p>An eight-point decline over two years, in the same period AI has become dramatically more capable and more widely deployed in clinical settings, is a genuine finding — trust in healthcare AI is moving in the opposite direction from the technology's abilities. But the number that actually explains what is happening sits one layer down: among people who already use AI to manage their own health or wellness, 88% trust it. Among people who don't, only 38% do. That is a fifty-point gap between two groups looking at the exact same technology.</p><p>This matches a separate Salesforce finding cited in our overview: patients are roughly three times more likely to trust an AI agent deployed by their own doctor than a public AI chatbot answering the same kind of question, based on a survey of more than 3,200 patients across eight countries. The pattern is consistent across every data set we found for this piece: trust in medical AI is not really a referendum on the technology. It is a referendum on the relationship — whose AI it is, whether a clinician stands behind it, and whether the patient chose to use it or had it used on them.</p><div class="trust-chart" role="img" aria-label="Bar chart: trust in AI for healthcare. All Americans 44%. Current AI health users 88%. Non-users 38%."><svg viewBox="0 0 720 260" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;font-family:'Inter',-apple-system,BlinkMacSystemFont,sans-serif;">
<text x="0" y="20" style="font-size:14px;font-weight:700;fill:#1A1A1A;">Trust in healthcare AI, by whether you already use it</text>
<text x="0" y="38" style="font-size:11px;fill:#5A5751;">Same question, put to people with and without direct experience</text>
<g style="font-size:12px;fill:#1A1A1A;">
<text x="0" y="80">All Americans</text>
<rect x="220" y="66" width="211" height="24" style="fill:#836E32;"/><text x="439" y="83" style="font-weight:700;">44%</text>
<text x="0" y="128">Already use AI for their health</text>
<rect x="220" y="114" width="422" height="24" style="fill:#0D0D0D;"/><text x="650" y="131" style="font-weight:700;">88%</text>
<text x="0" y="176">Don't use AI for their health</text>
<rect x="220" y="162" width="182" height="24" style="fill:#B9B3A6;"/><text x="410" y="179" style="font-weight:700;">38%</text>
</g>
<line x1="220" y1="58" x2="220" y2="196" style="stroke:#E4DFD5;stroke-width:1;"/>
<text x="0" y="220" style="font-size:10px;fill:#5A5751;">Source: Reach3 Insights &amp; Rival Technologies, 2026 Digital Health Trends (n=1,043), via eMarketer, Feb 2026</text>
</svg></div><h2>What Patients Actually Worry About Is Not What Gets Written About Most</h2><p>Most public discussion of medical AI focuses on accuracy: will it misdiagnose, will it miss something a doctor would catch. That concern is real — 36% of patients surveyed cite the accuracy of a diagnosis or treatment recommendation as their primary worry — but it is not the only one, and arguably not even the dominant one. Thirty percent of patients cite the privacy and security of their health data specifically as their leading concern, and separate research found patients expressed more worry about their health data being commercialised or sold than about algorithmic bias in the tool itself.</p><p>That ordering matters for anyone building or buying medical AI. A system can be clinically excellent and still fail the trust test if patients do not know, or do not believe, that their records stay inside the relationship they consented to. The Coalition for Health AI's January 2026 patient survey on health AI and transparency found the same underlying pattern in different language: concerns center less on whether AI exists in a given care pathway, and more on who is accountable when it is used, how its decisions are monitored, and what protections exist for the patient — with clear oversight measurably reassuring patients, especially in the use cases they trust least to begin with.</p><h2>A Related, Separate Finding: People Trust AI Chatbots for Health Information Far Less Than They Use Them</h2><p>KFF's ongoing Tracking Poll on Health Information and Trust adds a distinct angle: about three in ten US adults (29%) have used an AI tool in the past year for information or advice about their physical health, and 16% have used one for mental health advice — comparable to the share who turn to social media for health information, though still behind health providers and search engines. Trust has not caught up with that usage: only 36% of the people actually using these chatbots say they trust them to provide reliable health information, and that figure does not vary meaningfully by age. A notable share of AI-for-health users — disproportionately younger and lower-income — say they turned to AI specifically because of difficulty accessing or affording conventional care, which reframes some of this usage as a symptom of access gaps rather than an enthusiastic preference.</p><h2>The Cost of Getting It Wrong Is Highest Here of Any Sector</h2><p>Healthcare data is not just sensitive to the patient — it is expensive to lose. IBM's 2025 Cost of a Data Breach Report puts the average healthcare-sector breach at over $7.4 million, the highest of any industry it tracks, well above the $4.44 million global average cited in our overview piece. The same research found 97% of organisations that suffered an AI-related security incident had no proper AI access controls in place when it happened — meaning the exposure in most documented cases was not a sophisticated attack defeating good defences, but a straightforward gap in basic governance.</p><p>Wolters Kluwer's research on this point adds a structural detail worth knowing if you are evaluating a healthcare AI vendor rather than a hospital's own systems: the size of the health system materially changes what privacy and security concerns dominate, which means a governance checklist calibrated for a large academic medical centre will not automatically transfer to a small clinic group, and vice versa.</p><h2>What Actually Builds Trust — This Part Is Encouraging</h2><p>The most useful finding in this entire research area is that patient trust in medical AI is not a fixed, immovable scepticism. A survey of 3,000 US adults found people were significantly more willing to trust and choose an AI-assisted care pathway when specific, checkable conditions were met: demonstrably better clinical performance than the alternative, FDA approval, national or local certification, a clinician present in the loop rather than the AI operating alone, and training data that represented people like the patient rather than a narrower population.</p><p>None of those five conditions require a technological breakthrough. They are procurement and deployment decisions — the kind of checklist a hospital's compliance office can actually verify against a vendor's documentation, the same way our overview piece described certifications like SOC 2 and ISO 42001 as a concrete way to evaluate an AI vendor's data-handling posture in general. For healthcare specifically, HIPAA-ready configuration and a signed Business Associate Agreement are the floor, not the ceiling: the five factors above are what closes the remaining gap between "compliant" and "actually trusted by the patient it affects."</p><h2>The Honest Summary</h2><p>Healthcare is the sector in this research where the two sides of the argument are least in tension with each other, because they are answers to different questions. Is medical AI, deployed with real clinical validation, a clinician in the loop, and proper access controls, capable of being trusted with sensitive data? The evidence for what actually builds trust says yes, specifically and measurably. Is medical AI, as currently and unevenly deployed across a fragmented system with 97% of breached organisations lacking basic access controls, earning that trust today? The eight-point decline over two years says, for a lot of patients, not yet. Both are true, and the gap between them is a governance problem with a known shape, not a mystery.</p><p><a href="/blog/can-you-trust-ai-with-your-data.html">Back to the overview</a>, or continue to <a href="/blog/ai-data-trust-in-financial-services.html">how financial services is racing to scale AI faster than it can govern it</a>.</p><h3>Sources cited in this article</h3><ul><li>Reach3 Insights &amp; Rival Technologies, <em>2026 Digital Health Trends</em> (n=1,043), reported by eMarketer, February 2026</li><li>Salesforce, patient AI trust research (n=3,200+, 8 countries)</li><li>Coalition for Health AI (CHAI), patient survey on health AI and transparency, January 2026</li><li>KFF, <em>Tracking Poll on Health Information and Trust: Use of AI For Health Information and Advice</em>, late 2025/early 2026</li><li>IBM, <em>Cost of a Data Breach Report 2025</em></li><li>Wolters Kluwer, research on health system size and AI privacy/security concerns</li><li>US survey of 3,000 adults on factors building trust in medical AI (FDA approval, certification, clinician presence, representative data)</li></ul>
$ARTBODY$), 'deployed'
FROM pages p, content_components cc
WHERE p.site_id='4851f6fc-71cf-4160-a270-e03d6d3e0732' AND p.name='ai-data-trust-in-healthcare' AND cc.name='article-body';

INSERT INTO page_components (id, page_id, slot_name, position, component_id, content_data, build_status)
SELECT gen_random_uuid(), p.id, 'call-to-action', 3, cc.id, $CTAJSON${"headline": "Evaluating an AI system that will touch patient or client data?", "subheadline": "We build agent systems with the access controls, audit trail and human checkpoints this research shows actually build trust, not just the certifications on a data sheet. Contact us at leopardess@contactforsales.com or call +44 (0) 7934 524 911.", "primary_cta": "Start with an architecture conversation", "secondary_cta": "See how the platform runs in production"}$CTAJSON$::jsonb, 'deployed'
FROM pages p, content_components cc
WHERE p.site_id='4851f6fc-71cf-4160-a270-e03d6d3e0732' AND p.name='ai-data-trust-in-healthcare' AND cc.name='call-to-action';

SELECT p.name, count(pc.id) AS n_components
FROM pages p JOIN page_components pc ON pc.page_id=p.id
WHERE p.site_id='4851f6fc-71cf-4160-a270-e03d6d3e0732' AND p.name='ai-data-trust-in-healthcare'
GROUP BY p.name;

COMMIT;
